const calendarEvents = $('Extract Calendar Events').all().map(i => i.json);
const planRows = $input.all().map(i => i.json);
const user = $('Loop Users').item.json;
const today = $now.toFormat('yyyy-MM-dd');

// Build lookups
const planByEventId = {};
for (const row of planRows) {
  if (row.user_id === user.user_id && row.plan_date === today) {
    planByEventId[row.event_id] = row;
  }
}

const calByEventId = {};
for (const evt of calendarEvents) {
  calByEventId[evt.id] = evt;
}

const newEvents = [];
const changedEvents = [];
const deletedEvents = [];

// NEW: in calendar but not in plan
for (const evt of calendarEvents) {
  if (!planByEventId[evt.id]) {
    newEvents.push(evt);
  }
}

// CHANGED: in both, but time or location differ
for (const [eventId, evt] of Object.entries(calByEventId)) {
  const plan = planByEventId[eventId];
  if (!plan) continue;
  const terminalStates = ['arrived', 'cancelled', 'skipped', 'expired', 'departed', 'should_leave'];
  if (terminalStates.includes(plan.current_state)) continue;

  const calStart = evt.start?.dateTime || evt.start?.date;
  const calLocation = (evt.location || '').trim();
  const planStart = plan.start_time;
  const planLocation = (plan.location || '').trim();

  if (calStart !== planStart || calLocation !== planLocation) {
    changedEvents.push({
      calendar_event: evt,
      plan_row: plan,
      location_changed: calLocation !== planLocation,
      time_changed: calStart !== planStart
    });
  }
}

// DELETED: in plan but not in calendar
for (const [eventId, plan] of Object.entries(planByEventId)) {
  if (!calByEventId[eventId]) {
    const terminalStates = ['arrived', 'cancelled', 'skipped', 'expired', 'departed', 'should_leave'];
    if (!terminalStates.includes(plan.current_state)) {
      deletedEvents.push(plan);
    }
  }
}

return { json: {
  new_events: newEvents,
  changed_events: changedEvents,
  deleted_events: deletedEvents,
  user_id: user.user_id,
  ntfy_topic: user.ntfy_topic,
  has_changes: newEvents.length + changedEvents.length + deletedEvents.length > 0
}};

// Process each new event through the same pipeline as WF1:
// 1. Classify (Sub-WF D)
// 2. If not online: geocode, calculate departure (Sub-WF A), get weather (Sub-WF B)
// 3. Write to daily_plan

const data = $json;
const newEvents = data.new_events;

// Return new events for processing by subsequent nodes
return newEvents.map(evt => ({ json: {
  ...evt,
  user_id: data.user_id,
  ntfy_topic: data.ntfy_topic,
  sync_type: 'new'
}}));

// Decide origin for this mid-day event:
// 1. Check existing daily_plan for arrived/departed events (user is away from home)
// 2. If user arrived at a previous event → origin = that event's location, at_home = false
// 3. If user departed but not arrived → origin = home, at_home = false
// 4. Else → origin = HOME_COORDS, at_home = true (WF4 corrects in real-time via GPS)

const geocode = $json; // from geocode response
const user = $('Loop Users').item.json;
const newEvent = $('Loop New Events').item.json;
const HOME_COORDS = $vars.HOME_COORDS;
const HOME_RADIUS_METERS = parseInt($vars.HOME_RADIUS_METERS) || 200;

// Extract geocoded coords
const geo = geocode.results?.[0]?.geometry?.location;
const locationCoords = geo ? `${geo.lat},${geo.lng}` : '';

// Check existing daily_plan for this user's events today
const existingPlan = $('Read Existing Daily Plan').all().map(i => i.json);
const userEvents = existingPlan.filter(r => r.user_id === user.user_id);

// Look for arrived events (most recent first by start_time)
const arrivedEvents = userEvents
  .filter(r => r.current_state === 'arrived' && r.location_coords)
  .sort((a, b) => new Date(b.start_time) - new Date(a.start_time));

let originCoords, originType, atHome;

if (arrivedEvents.length > 0) {
  // User arrived at a previous event — use that location as origin
  originCoords = arrivedEvents[0].location_coords;
  originType = 'event';
  atHome = false;
} else {
  // Check if user has departed (traveling but not yet arrived)
  const departedEvents = userEvents.filter(r => r.current_state === 'departed');
  if (departedEvents.length > 0) {
    originCoords = HOME_COORDS;
    originType = 'home';
    atHome = false;
  } else {
    // Default: user is at home
    originCoords = HOME_COORDS;
    originType = 'home';
    atHome = true;
  }
}

const calStart = newEvent.start?.dateTime || newEvent.start?.date;
const calEnd = newEvent.end?.dateTime || newEvent.end?.date;

return { json: {
  event_id: newEvent.id,
  user_id: user.user_id,
  plan_date: $now.toFormat('yyyy-MM-dd'),
  title: newEvent.summary || '(no title)',
  location: newEvent.location || '',
  location_coords: locationCoords,
  start_time: calStart,
  end_time: calEnd,
  origin_coords: originCoords,
  origin_type: originType,
  at_home: atHome,
  is_online: false,
  is_tentative: $('Classify New Event').item.json.is_tentative,
  ntfy_topic: user.ntfy_topic,
  _geocode_failed: !geo
}};

// Merge departure + weather into a complete daily_plan row
const eventData = $('Determine Origin + At-Home for New Event').item.json;
const departure = $('Calculate Departure').item.json;
const weather = $json; // from Sub-WF B

const depTime = new Date(departure.departure_time || eventData.start_time);
const fourAM = new Date(depTime); fourAM.setHours(4, 0, 0, 0);

// Calculate reminder times with dress_cap support
const classified = $('Classify New Event').item.json;
const dressCap = classified.dress_cap || 0;
const ALL_DRESS_INTERVALS = ($vars.DRESS_REMINDER_INTERVALS || '90,60,30,15').split(',').map(Number);
const DRESS_INTERVALS = dressCap > 0
  ? ALL_DRESS_INTERVALS.filter(n => n <= dressCap)
  : ALL_DRESS_INTERVALS;
const maxDressMin = DRESS_INTERVALS.length > 0 ? Math.max(...DRESS_INTERVALS) : 0;
const dressedEarliest = maxDressMin > 0
  ? new Date(depTime.getTime() - maxDressMin * 60 * 1000)
  : depTime;
const remindDressed = dressedEarliest < fourAM ? fourAM.toISOString() : dressedEarliest.toISOString();

return { json: {
  event_id: eventData.event_id,
  user_id: eventData.user_id,
  plan_date: eventData.plan_date,
  title: eventData.title,
  location: eventData.location,
  location_coords: eventData.location_coords,
  start_time: eventData.start_time,
  end_time: eventData.end_time,
  origin_coords: eventData.origin_coords,
  origin_type: eventData.origin_type,
  at_home: eventData.at_home,
  is_online: eventData.is_online,
  is_tentative: eventData.is_tentative,
  ntfy_topic: eventData.ntfy_topic,
  dress_cap: dressCap,
  departure_time: departure.departure_time || '',
  commute_minutes: departure.commute_minutes || 0,
  commute_mode: departure.commute_mode || '',
  weather_worst: weather.weather_worst || '',
  clothing_advice: weather.clothing_advice || '',
  remind_dressed: remindDressed,
  remind_60: new Date(depTime.getTime() - 60 * 60 * 1000).toISOString(),
  remind_30: new Date(depTime.getTime() - 30 * 60 * 1000).toISOString(),
  remind_15: new Date(depTime.getTime() - 15 * 60 * 1000).toISOString(),
  remind_now: departure.departure_time || '',
  reminders_sent: '',
  current_state: 'planned',
  state_version: 0,
  sync_updated: $now.toISO(),
  departed_at: '',
  _departure_within_2h: departure.departure_time
    ? (new Date(departure.departure_time).getTime() - Date.now()) < 2 * 60 * 60 * 1000
    : false
}};

const data = $('Diff Calendar vs Plan').item.json;
const changes = data.changed_events;

if (changes.length === 0) {
  return [{ json: { _no_changes: true } }];
}

return changes.map(c => ({ json: {
  ...c.plan_row,
  new_start_time: c.calendar_event.start?.dateTime || c.calendar_event.start?.date,
  new_end_time: c.calendar_event.end?.dateTime || c.calendar_event.end?.date,
  new_location: (c.calendar_event.location || '').trim(),
  location_changed: c.location_changed,
  time_changed: c.time_changed,
  ntfy_topic: $('Diff Calendar vs Plan').item.json.ntfy_topic,
  sync_type: 'changed'
}}));

// Recalculate departure and reminders based on what changed
const row = $('Loop Changed Events').item.json;
const locationChanged = row.location_changed;
const newStart = row.new_start_time;
const newEnd = row.new_end_time;

let depTime, commuteMin, commuteMode, locationCoords, weatherWorst, clothingAdvice;

if (locationChanged) {
  // Full recalculation happened via Sub-WF A + B
  const departure = $('Recalculate Departure').item.json;
  const weather = $('Recalculate Weather').item.json;
  const geocode = $('Re-Geocode Changed Location').item.json;
  const geo = geocode.results?.[0]?.geometry?.location;
  locationCoords = geo ? `${geo.lat},${geo.lng}` : row.location_coords;
  depTime = new Date(departure.departure_time);
  commuteMin = departure.commute_minutes;
  commuteMode = departure.commute_mode;
  weatherWorst = weather.weather_worst || '';
  clothingAdvice = weather.clothing_advice || '';
} else {
  // Time-only change: recalculate departure from existing commute_minutes
  locationCoords = row.location_coords;
  commuteMin = parseInt(row.commute_minutes) || 0;
  commuteMode = row.commute_mode || '';
  depTime = new Date(new Date(newStart).getTime() - commuteMin * 60000); // commute_minutes already includes mode-specific buffer from Sub-WF A
  weatherWorst = row.weather_worst || '';
  clothingAdvice = row.clothing_advice || '';
}

const fourAM = new Date(depTime); fourAM.setHours(4, 0, 0, 0);

// Preserve dress_cap from existing row (set by Sub-WF D during initial classification)
const dressCap = parseInt(row.dress_cap) || 0;
const ALL_DRESS_INTERVALS = ($vars.DRESS_REMINDER_INTERVALS || '90,60,30,15').split(',').map(Number);
const DRESS_INTERVALS = dressCap > 0
  ? ALL_DRESS_INTERVALS.filter(n => n <= dressCap)
  : ALL_DRESS_INTERVALS;
const maxDressMin = DRESS_INTERVALS.length > 0 ? Math.max(...DRESS_INTERVALS) : 0;
const dressedEarliest = maxDressMin > 0
  ? new Date(depTime.getTime() - maxDressMin * 60 * 1000)
  : depTime;
const remindDressed = dressedEarliest < fourAM ? fourAM.toISOString() : dressedEarliest.toISOString();

const oldDep = row.departure_time ? new Date(row.departure_time) : null;
const diffMin = (oldDep && !isNaN(oldDep.getTime())) ? Math.round((oldDep.getTime() - depTime.getTime()) / 60000) : 0; // positive = moved earlier; 0 if no previous departure

return { json: {
  event_id: row.event_id,
  start_time: newStart,
  end_time: newEnd,
  location: locationChanged ? row.new_location : row.location,
  location_coords: locationCoords,
  departure_time: depTime.toISOString(),
  commute_minutes: commuteMin,
  commute_mode: commuteMode,
  weather_worst: weatherWorst,
  clothing_advice: clothingAdvice,
  remind_dressed: remindDressed,
  remind_60: new Date(depTime.getTime() - 60 * 60 * 1000).toISOString(),
  remind_30: new Date(depTime.getTime() - 30 * 60 * 1000).toISOString(),
  remind_15: new Date(depTime.getTime() - 15 * 60 * 1000).toISOString(),
  remind_now: depTime.toISOString(),
  state_version: (parseInt(row.state_version) || 0) + 1,
  sync_updated: $now.toISO(),
  ntfy_topic: row.ntfy_topic,
  title: row.title,
  _diff_minutes: diffMin,
  _moved_earlier_15: diffMin > 15
}};

const data = $('Diff Calendar vs Plan').item.json;
const deleted = data.deleted_events;

if (deleted.length === 0) {
  return [{ json: { _no_deletions: true } }];
}

const now = new Date();
const sixtyMinAgo = new Date(now.getTime() - 60 * 60 * 1000);

return deleted.map(row => {
  // Consent-safety: if user recently cancelled, honor that over "skipped"
  const useCancelled = row.cancel_requested_at
    && new Date(row.cancel_requested_at) > sixtyMinAgo;

  return { json: {
    ...row,
    new_state: useCancelled ? 'cancelled' : 'skipped',
    state_version: (parseInt(row.state_version) || 0) + 1,
    sync_type: 'deleted'
  }};
});

// After processing all deletions, check if this user has any remaining non-terminal events
const data = $('Diff Calendar vs Plan').item.json;
const planRows = $('Read Existing Daily Plan').all().map(i => i.json);
const userId = data.user_id;
const today = $now.toFormat('yyyy-MM-dd');
const terminalStates = ['arrived', 'cancelled', 'skipped', 'expired'];

const remaining = planRows.filter(r =>
  r.user_id === userId
  && r.plan_date === today
  && !terminalStates.includes(r.current_state)
  && r.is_online !== 'TRUE'
);

// Account for events we just deleted/skipped in this run
const deletedIds = new Set(data.deleted_events.map(e => e.event_id));
const reallyRemaining = remaining.filter(r => !deletedIds.has(r.event_id));

return { json: {
  should_stop_tracking: reallyRemaining.length === 0,
  ntfy_topic: data.ntfy_topic,
  user_id: userId
}};
